    lines = input_data.strip().split('\n')
    n = int(lines[0])

    if n < 2:
        return '-1\n'

    # Parse cost matrix
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        line = lines[i + 1].strip().split()
