def midpoint(p1, p2):
    return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2, (p1[2] + p2[2]) / 2)

def circumcenter_3pts(p1, p2, p3):
    ax, ay, az = p1
    bx, by, bz = p2
    cx, cy, cz = p3

    vx = bx - ax
    vy = by - ay
    vz = bz - az

    wx = cx - ax
    wy = cy - ay
    wz = cz - az

    num = [
        vy * wz - vz * wy,
        vz * vx - vx * vz,
        vx * vy - vy * vx
    ]

    tx = -num[2]
    ty = -num[0]
    tz = -num[1]

    len_t = math.sqrt(tx**2 + ty**2 + tz**2)
    if len_t > 1e-9:
        tx /= len_t
        ty /= len_t
        tz /= len_t
        mu = (ax + bx + cx) / 3
        nu = (ay + by + cy) / 3
        ov = (az + bz + cz) / 3
        dist = math.sqrt(2 * (vx**2 + vy**2 + vz**2) + 2 * (wx**2 + wy**2 + wz**2))
        alt = dist / 2.0
        cx = mu + tx * alt
        cy = nu + ty * alt
        cz = ov + tz * alt
        return (cx, cy, cz)
    else:
        return midpoint(p1, p2)

def circumcenter_4pts(p1, p2, p3, p4):
    ax, ay, az = p1
    bx, by, bz = p2
    cx, cy, cz = p3
    dx, dy, dz = p4

    A = [
        [2*(ax-bx), 2*(ay-by), 2*(az-bz)],
        [2*(ax-cx), 2*(ay-cy), 2*(az-cz)],
        [2*(ax-dx), 2*(ay-dy), 2*(az-dz)]
    ]
    B = [
        (ax**2 - bx**2 + ay**2 - by**2 + az**2 - bz**2),
        (ax**2 - cx**2 + ay**2 - cy**2 + az**2 - cz**2),
        (ax**2 - dx**2 + ay**2 - dy**2 + az**2 - dz**2)
    ]

    for i in range(3):
        if abs(A[i][i]) < 1e-10:
            for j in range(i+1, 3):
                if abs(A[j][i]) > 1e-10:
                    A[i], A[j] = A[j], A[i]
                    B[i], B[j] = B[j], B[i]

    a00, a01, a02 = A[0][0], A[0][1], A[0][2]
    a10, a11, a12 = A[1][0], A[1][1], A[1][2]
    a20, a21, a22 = A[2][0], A[2][1], A[2][2]
    b0, b1, b2 = B[0], B[1], B[2]

    d = a00 * a11 * a22 + a01 * a12 * a20 + a02 * a10 * a21
    - a02 * a11 * a20 - a01 * a10 * a22 - a00 * a12 * a21

    x = (b0 * (a11 * a22 - a12 * a21) -
         a00 * (b1 * (a22 - a12 * a21) -
                 a01 * (b1 * a22 + a02 * (b2 * (a21)))) / d)
        # = (b0*(a11*a22 - a12*a21) - a01*(b1*(a12*a21) + b2*(a11*a22)))

    me = (a00*a11-a10*a01, a00*a12-a10*a02, a00*a21-a20*a01)

    y = (b0 * me[0] + a01 * b1 + b10 * a11 * a22 + a02 * b2 * a11 * a22) / d

    z = (b0 * me[2] + a01 * b1 * a02 + a10 * b2 * a02) / d

    return (x % d, y, z)

