def is_geometric(arr):
    """Check if list is a geometric progression"""
    n = len(arr)
    if n <= 2:
        return True

    # Find the ratio from first two elements
    a = arr[0]
    b = arr[1]

    if a == 0:
        # First element is 0 - all must be 0
        return all(x == 0 for x in arr)

    if b == 0:
        # Second element is 0 - ratio is 0, so all subsequent must be 0
        for i in range(2, n):
            if arr[i] != 0:
                return False
        return True

    ratio_num = b
    ratio_den = a

    # Check all ratios are the same
    for i in range(2, n):
        cur = arr[i]
        prev = arr[i-1]

        if prev == 0:
            if cur != 0:
                return False
        elif (ratio_num * prev) != (ratio_den * cur):
            return False

    return True


