    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.MOD = 10**9 + 7

    def parse(self):
        return self.parse_expression()

    def peek(self):
        if self.pos < len(self.s):
            return self.s[self.pos]
        return '\0'

    def consume(self, c=None):
        if c is not None and self.s[self.pos] != c:
            raise ValueError(f"Expected '{c}' but got '{self.s[self.pos]}'")
        ch = self.s[self.pos]
        self.pos += 1
        return ch

    def parse_expression(self):
        # expression ::= term | expression '+' term
        result = self.parse_term()

        while self.peek() == '+':
            self.consume('+')
            right = self.parse_term()
            result = self.concat(result, right)

        return result

    def parse_term(self):
        # term ::= number | number '-' number | number '(' expression ')'
        num, num_len = self.parse_number()
        num_val = num % self.MOD

        if self.peek() == '-':
            self.consume('-')
            right, right_len = self.parse_number()
            # range_concat(num, right) -> concatenate l to r
