import math

def minimum_distance_segment(p1, p2, q1, q2):
    """Calculate minimum distance between two line segments."""

    def cross_product(u, v):
        return u[0] * v[1] - u[1] * v[0]

    import math

    ax, ay = p2[0] - p1[0], p2[1] - p1[1]  # Vector A_start -> A_end
    bx, by = q2[0] - q1[0], q2[1] - q1[1]  # Vector B_start -> B_end
    ry, rx = q1[0] - p1[0], q1[1] - p1[1]  # Vector A_start -> B_start
    ry2, rx2 = q2[0] - p1[0], q2[1] - p1[1]  # Vector A_start -> B_end

    denom = ax * bx + ay * by  # dot product

    if abs(denom) < 1e-9:  # Comparison is parallel
        min_sq = min(dist_sq(p1, q1), dist_sq(p1, q2), dist_sq(p2, q1), dist_sq(p2, q2))
    else:
        t = (bx * rx + by * ry) / denom
        if t < 0:
            t = 0
        elif t > 1:
            t = 1

        # Find closest point on A's segment
        px = p1[0] + t * ax
        py = p1[1] + t * ay

        # Distance to line from B_start
        min_sq = (q1[0] - px)**2 + (q1[1] - py)**2

    return math.sqrt(min_sq)

def dist_sq(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def solution(input_data):
    lines = input_data.strip().split('\n')

    parts = lines[1].split()
    d1 = int(parts[0])
    d2 = int(parts[1])

    N = int(lines[0])
    positions = []
    for i in range(2, 2 + N):
        pos_data = list(map(int, lines[i].split()))
        positions.append((pos_data[0], pos_data[1], pos_data[2], pos_data[3]))

    def dist(p1, p2):
        return math.sqrt(dist_sq(p1, p2))

    def min_dist(p1, p2, q1, q2):
        return minimum_distance_segment(p1, p2, q1, q2)

    hellos = 0
    exceeded_d2 = False

    for i in range(1, N):
        A_from = (positions[i-1][0], positions[i-1][1])
        A_to = (positions[i][0], positions[i][1])
        B_from = (positions[i-1][2], positions[i-1][3])
        B_to = (positions[i][2], positions[i][3])

        # Calculate minimum distance during this interval
        d_val = min_dist(A_from, A_to, B_from, B_to)

        # Also check maximum distance (to determine if d2 was exceeded)
        if A_from == A_to and B_from == B_to:
            d_max = dist(A_from, B_from)
        elif A_from == A_to:
            d_max = max(dist(A_from, B_from), dist(A_from, B_to))
        elif B_from == B_to:
            d_max = max(dist(A_from, B_from), dist(A_to, B_from))
        else:
            d_max = max(dist(A_from, B_from), dist(A_from, B_to), dist(A_to, B_from), dist(A_to, B_to))

        # Check hello condition
        if d_val <= d1:
            # Could say hello if not exceeded d2 after last hello
            if not exceeded_d2:
                hellos += 1

        # Check if d2 was exceeded during this interval
        if d_max > d2:
            exceeded_d2 = True

    return str(hellos)

