def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return 'Impossible'

    n, m = map(int, lines[0].split())
    edges = []
    idx = 1
    for _ in range(m):
        if idx < len(lines) and lines[idx]:
            parts = lines[idx].split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                idx += 1
                edges.append((a, b))

    if m == 0:
        return ''

    # Build conflict graph for crossing edges
    adj = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            u1, v1 = edges[i]
            u2, v2 = edges[j]

            # Normalize so a < b
            a1, b1 = sorted([u1, v1])
            a2, b2 = sorted([u2, v2])

            # Edges cross if exactly one endpoint of edge 2 is strictly between endpoints of edge 1
            count = sum(1 for x in [a2, b2] if a1 < x < b1)

            if count == 1:
                adj[i].append(j)
                adj[j].append(i)

    # Try to 2-color the conflict graph
    vis = [None] * m
    ans = [''] * m
    possible = True

    def dfs(u, color):
        nonlocal possible
        if not possible:
            return
        vis[u] = color
        ans[u] = 'i' if color == 0 else 'o'

        for v in adj[u]:
            if vis[v] is None:
                dfs(v, 1 - color)
            elif vis[v] != color:
                possible = False

    for i in range(m):
        if vis[i] is None:
            dfs(i, 0)
            if not possible:
                break

    if not possible:
        return 'Impossible'

    return ''.join(ans) + '\n'

