    for tri in combinations(range(n), 3):
        i, j, k = tri
        a = dist(i, j)
        b = dist(j, k)
        c = dist(k, i)

        if is_collinear(centers[i], centers[j], centers[k]):
            continue

        s = (a + b + c) / 2
        area_sq = s * (s - a) * (s - b) * (s - c)

        if area_sq <= 1e-9:
            continue

        r = (a * b * c) / (4 * math.sqrt(area_sq))
        max_circumradius = max(max_circumradius, r)

    if max_circumradius == 0:
        return "-1"

    return str(max_circumradius)

